CREATE OR REPLACE FUNCTION books_fts_compute(
    p_title    text,
    p_keywords text,
    p_authors  text
) RETURNS tsvector AS $$
BEGIN
    RETURN
        setweight(to_tsvector('russian', coalesce(p_title,    '')), 'A') ||
        setweight(to_tsvector('russian', coalesce(p_authors,  '')), 'B') ||
        setweight(to_tsvector('russian', coalesce(p_keywords, '')), 'C');
END;
$$ LANGUAGE plpgsql IMMUTABLE;;

CREATE OR REPLACE FUNCTION books_fts_trigger() RETURNS trigger AS $$
DECLARE
    v_authors text;
BEGIN
    SELECT string_agg(
               coalesce(p.last_name,   '') || ' ' ||
               coalesce(p.first_name,  '') || ' ' ||
               coalesce(p.middle_name, ''),
               ' ')
      INTO v_authors
      FROM book_authors ba
      JOIN persons p ON p.id = ba.person_id
     WHERE ba.book_id = NEW.id;

    NEW.fts_tsv := books_fts_compute(NEW.title, NEW.keywords, v_authors);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;;

CREATE OR REPLACE FUNCTION book_authors_fts_trigger() RETURNS trigger AS $$
DECLARE
    v_book_id bigint;
    v_authors text;
    v_title   text;
    v_keywords text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_book_id := OLD.book_id;
    ELSE
        v_book_id := NEW.book_id;
    END IF;

    SELECT string_agg(
               coalesce(p.last_name,   '') || ' ' ||
               coalesce(p.first_name,  '') || ' ' ||
               coalesce(p.middle_name, ''),
               ' ')
      INTO v_authors
      FROM book_authors ba
      JOIN persons p ON p.id = ba.person_id
     WHERE ba.book_id = v_book_id;

    SELECT title, keywords INTO v_title, v_keywords
      FROM books WHERE id = v_book_id;

    UPDATE books
       SET fts_tsv = books_fts_compute(v_title, v_keywords, v_authors)
     WHERE id = v_book_id;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$ LANGUAGE plpgsql;;

CREATE OR REPLACE FUNCTION persons_fts_trigger() RETURNS trigger AS $$
BEGIN
    NEW.fts_tsv := to_tsvector('russian',
        coalesce(NEW.last_name,   '') || ' ' ||
        coalesce(NEW.first_name,  '') || ' ' ||
        coalesce(NEW.middle_name, ''));
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;;
